factorial(n) BEGIN
  IF (n = 0 OR n = 1) THEN BEGIN
    RETURN 1;
  END
  RETURN n * factorial(n - 1);
END

factorialTD(n, Tabla[n]) BEGIN
  IF (n = 0 OR n = 1) THEN BEGIN
    RETURN 1;
  END
  IF (Tabla[n] != -1) THEN BEGIN
    RETURN Tabla[n];
  END
  Tabla[n] <- n * factorialTD(n - 1, Tabla);
  RETURN Tabla[n];
END

factorialBU(n) BEGIN
  Tabla[0] <- 1;
  Tabla[1] <- 1;
  FOR i <- 2 TO n DO BEGIN
    Tabla[i] <- Tabla[i - 1] * i;
  END
  RETURN Tabla[n];
END

fibTD(n, Tabla[n]) BEGIN
  IF (n = 0 OR n = 1) THEN BEGIN
    RETURN n;
  END
  IF (Tabla[n] != -1) THEN BEGIN
    RETURN Tabla[n];
  END
  Tabla[n] <- fibTD(n - 1, Tabla) + fibTD(n - 2, Tabla);
  RETURN Tabla[n];
END

fibBU(n) BEGIN
  Tabla[0] <- 0;
  Tabla[1] <- 1;
  FOR i <- 2 TO n DO BEGIN
    Tabla[i] <- Tabla[i - 1] + Tabla[i - 2];
  END
  RETURN Tabla[n];
END

fibBUOptimizado(n) BEGIN
  IF (n = 0 OR n = 1) THEN BEGIN
    RETURN n;
  END
  anterior2 <- 0;
  anterior1 <- 1;
  FOR i <- 2 TO n DO BEGIN
    actual <- anterior1 + anterior2;
    anterior2 <- anterior1;
    anterior1 <- actual;
  END
  RETURN actual;
END

