LCS(X[m], Y[n]) BEGIN
 FOR i <- 0 TO m DO BEGIN
 dp[i][0] <- 0;
 END
 FOR j <- 0 TO n DO BEGIN
 dp[0][j] <- 0;
 END

 FOR i <- 1 TO m DO BEGIN
 FOR j <- 1 TO n DO BEGIN
 IF (X[i] = Y[j]) THEN BEGIN
 dp[i][j] <- dp[i - 1][j - 1] + 1;
 path[i][j] <- "diagonal";
 END
 ELSE BEGIN
 IF (dp[i - 1][j] >= dp[i][j - 1]) THEN BEGIN
 dp[i][j] <- dp[i - 1][j];
 path[i][j] <- "arriba";
 END
 ELSE BEGIN
 dp[i][j] <- dp[i][j - 1];
 path[i][j] <- "izquierda";
 END
 END
 END
 END

 RETURN dp[m][n];
END

reconstruirLCS(X[m], Y[n], dp[m][n]) BEGIN
 i <- m;
 j <- n;
 solucion <- "";

 WHILE (i > 0 AND j > 0) DO BEGIN
 IF (X[i] = Y[j]) THEN BEGIN
 solucion <- X[i] + solucion;
 i <- i - 1;
 j <- j - 1;
 END
 ELSE BEGIN
 IF (dp[i - 1][j] >= dp[i][j - 1]) THEN BEGIN
 i <- i - 1;
 END
 ELSE BEGIN
 j <- j - 1;
 END
 END
 END

 RETURN solucion;
END

LCSTD(X[m], Y[n], i, j, memo[m][n]) BEGIN
 IF (i = 0 OR j = 0) THEN BEGIN
 RETURN 0;
 END

 IF (memo[i][j] != -1) THEN BEGIN
 RETURN memo[i][j];
 END

 IF (X[i] = Y[j]) THEN BEGIN
 memo[i][j] <- 1 + LCSTD(X, Y, i - 1, j - 1, memo);
 END
 ELSE BEGIN
 a <- LCSTD(X, Y, i - 1, j, memo);
 b <- LCSTD(X, Y, i, j - 1, memo);
 memo[i][j] <- max(a, b);
 END

 RETURN memo[i][j];
END
